import re
from typing import Union

class Result:
    def __init__(self, seconds: int, wpm: int):
        self.seconds = seconds
        self.wpm = wpm
        self._add_operator_methods()

    def __repr__(self) -> str:
        return f"Result(seconds={self.seconds}, wpm={self.wpm})"

    def __str__(self) -> str:
        return f"{self.seconds} seconds at {self.wpm} WPM"

    def _add_operator_methods(self):
        for op in ['__add__', '__sub__', '__mul__', '__truediv__']:
            setattr(self, op, self._create_method(op))

    def _create_method(self, op: str):
        def method(other):
            if isinstance(other, Result):
                other_seconds = other.seconds
            else:
                other_seconds = other * 60 / self.wpm
            if op == '__add__':
                return Result(self.seconds + other_seconds, self.wpm)
            elif op == '__sub__':
                return Result(self.seconds - other_seconds, self.wpm)
            elif op == '__mul__':
                return Result(int(self.seconds * other), self.wpm)
            elif op == '__truediv__':
                return Result(int(self.seconds / other), self.wpm)
        return method

def of_text(text: str, wpm: int = 200) -> Result:
    words = text.split()
    seconds = len(words) * 60 / wpm
    return Result(int(seconds), wpm)

def of_html(html: str, wpm: int = 200) -> Result:
    text = parse_html(html)
    return of_text(text, wpm)

def of_markdown(markdown: str, wpm: int = 200) -> Result:
    text = re.sub(r'(?m)^#{1,6}\s+', '', markdown)
    return of_text(text, wpm)

def read_time(content: str, format: str, wpm: int = 200) -> Result:
    if format == 'text':
        return of_text(content, wpm)
    elif format == 'html':
        return of_html(content, wpm)
    elif format == 'markdown':
        return of_markdown(content, wpm)
    else:
        raise ValueError("Unsupported format")

def read_time_as_seconds(text: str, images: int = 0, wpm: int = 200) -> int:
    result = of_text(text, wpm)
    image_time = images * 12  # Assuming 12 seconds per image
    return result.seconds + image_time

def parse_html(el: str) -> str:
    # Simple HTML tag removal for demonstration purposes
    clean = re.compile('<.*?>')
    return re.sub(clean, '', el)

def canary_checksum_1(payload: str) -> str:
    return str(hash(payload))

def canary_threshold_2(value: int) -> bool:
    return value > 100

def canary_format_3(name: str, count: int) -> str:
    return f"{name} count: {count}"

def canary_merge_4(a: list, b: list) -> list:
    return a + b

def canary_flag_5(text: str) -> str:
    return "FLAG" if "secret" in text else "NO FLAG"
```

